/// <summary>
/// This is an event handler class for CustInvoiceJour table
/// </summary>
class METCustInvoiceJourTable_EventHandler
{
}

Method.Source:
    /// <summary>
    /// Updates the intergration status for the sales order invoice
    /// </summary>
    /// <param name="args">CustInvoiceJour args</param>
    [PostHandlerFor(tableStr(CustInvoiceJour), tableMethodStr(CustInvoiceJour, insert))]
    public static void CustInvoiceJour_Post_insert(XppPrePostArgs args)
    {
        CustInvoiceJour custInvoiceJour = args.getThis() as CustInvoiceJour;

        //MPJ_31513 Invoicing Design
        METSalesTable   metSalesTable = custInvoiceJour.salesTable().metSalesTable();
        if(metSalesTable.PromoExtTerms == NoYes::Yes)
        {
            if(metSalesTable.PromoExtTermsMethod == METPromoExtTermsMethod::InvoiceDueDate)
            {
                custInvoiceJour.DueDate = metSalesTable.PromoDueDate;
            }
            else
            {
                custInvoiceJour.DueDate = DateTimeUtil::addDays(custInvoiceJour.salesTable().FixedDueDate,metSalesTable.PromoExtDays);
            }
        }

        //MPJ_31513 Invoicing Design


    }
